import { test, expect } from "@playwright/test";

// Helper: sign in as standard user
async function signIn(page: import("@playwright/test").Page) {
  await page.goto("/");
  await page.getByTestId("username").fill(process.env["AQA_APP_USER"] ?? "standard_user");
  await page.getByTestId("password").fill(process.env["AQA_APP_PASS"] ?? "secret_sauce");
  await page.getByTestId("login-button").click();
  await expect(page.getByTestId("inventory-container"), "Precondition: product list must be visible after sign-in").toBeVisible();
}

test.describe("Product list", () => {

  // @story:111
  // @ac:1
  // @design:D1
  // @type:functional
  // @technique:state-transition
  test("AC-1 Product list is sorted A to Z by name when it first opens", async ({ page }) => {
    await test.step("Given I am on the product list page", async () => {
      await signIn(page);
    });

    await test.step("Then the sort selector shows 'Name (A to Z)'", async () => {
      const sortSelect = page.getByTestId("product-sort-container");
      await expect(sortSelect, "Sort selector must show 'Name (A to Z)' as the default").toHaveValue("az");
    });

    await test.step("And the products are sorted by name A to Z", async () => {
      const names = page.locator(".inventory_item_name");
      const count = await names.count();
      expect(count, "Precondition: at least one product must be visible").toBeGreaterThan(0);
      const texts: string[] = [];
      for (let i = 0; i < count; i++) {
        texts.push((await names.nth(i).textContent()) ?? "");
      }
      const sorted = [...texts].sort((a, b) => a.localeCompare(b));
      expect(texts, "Products must be sorted alphabetically A to Z").toEqual(sorted);
    });
  });

  // @story:111
  // @ac:2
  // @design:D2
  // @type:functional
  // @technique:state-transition
  test("AC-2 Sorting by name Z to A reverses the order", async ({ page }) => {
    await test.step("Given I am on the product list page", async () => {
      await signIn(page);
    });

    await test.step("When I select the sort option 'Name (Z to A)'", async () => {
      const sortSelect = page.getByTestId("product-sort-container");
      await sortSelect.selectOption("za");
    });

    await test.step("Then the sort selector shows 'Name (Z to A)'", async () => {
      const sortSelect = page.getByTestId("product-sort-container");
      await expect(sortSelect, "Sort selector must reflect the selected option 'Name (Z to A)'").toHaveValue("za");
    });

    await test.step("And the products are sorted by name Z to A", async () => {
      const names = page.locator(".inventory_item_name");
      const count = await names.count();
      expect(count, "Precondition: at least one product must be visible").toBeGreaterThan(0);
      const texts: string[] = [];
      for (let i = 0; i < count; i++) {
        texts.push((await names.nth(i).textContent()) ?? "");
      }
      const sorted = [...texts].sort((a, b) => b.localeCompare(a));
      expect(texts, "Products must be sorted alphabetically Z to A").toEqual(sorted);
    });
  });

  // @story:111
  // @ac:3
  // @design:D3
  // @type:functional
  // @technique:state-transition
  test("AC-3a Sorting by price low to high lists the cheapest product first", async ({ page }) => {
    await test.step("Given I am on the product list page", async () => {
      await signIn(page);
    });

    await test.step("When I select the sort option 'Price (low to high)'", async () => {
      const sortSelect = page.getByTestId("product-sort-container");
      await sortSelect.selectOption("lohi");
    });

    await test.step("Then the sort selector shows 'Price (low to high)'", async () => {
      const sortSelect = page.getByTestId("product-sort-container");
      await expect(sortSelect, "Sort selector must reflect the selected option 'Price (low to high)'").toHaveValue("lohi");
    });

    await test.step("And the products are sorted by price low to high", async () => {
      const prices = page.locator(".inventory_item_price");
      const count = await prices.count();
      expect(count, "Precondition: at least one product must be visible").toBeGreaterThan(0);
      const values: number[] = [];
      for (let i = 0; i < count; i++) {
        const text = (await prices.nth(i).textContent()) ?? "";
        values.push(parseFloat(text.replace("$", "")));
      }
      const sorted = [...values].sort((a, b) => a - b);
      expect(values, "Products must be sorted by price from low to high (cheapest first)").toEqual(sorted);
    });
  });

  // @story:111
  // @ac:3
  // @design:D4
  // @type:functional
  // @technique:state-transition
  test("AC-3b Sorting by price high to low lists the most expensive product first", async ({ page }) => {
    await test.step("Given I am on the product list page", async () => {
      await signIn(page);
    });

    await test.step("When I select the sort option 'Price (high to low)'", async () => {
      const sortSelect = page.getByTestId("product-sort-container");
      await sortSelect.selectOption("hilo");
    });

    await test.step("Then the sort selector shows 'Price (high to low)'", async () => {
      const sortSelect = page.getByTestId("product-sort-container");
      await expect(sortSelect, "Sort selector must reflect the selected option 'Price (high to low)'").toHaveValue("hilo");
    });

    await test.step("And the products are sorted by price high to low", async () => {
      const prices = page.locator(".inventory_item_price");
      const count = await prices.count();
      expect(count, "Precondition: at least one product must be visible").toBeGreaterThan(0);
      const values: number[] = [];
      for (let i = 0; i < count; i++) {
        const text = (await prices.nth(i).textContent()) ?? "";
        values.push(parseFloat(text.replace("$", "")));
      }
      const sorted = [...values].sort((a, b) => b - a);
      expect(values, "Products must be sorted by price from high to low (most expensive first)").toEqual(sorted);
    });
  });

  // @story:111
  // @design:D5
  // @type:accessibility
  // @technique:checklist-based
  test("AC-story Product list page passes accessibility checks", async ({ page }) => {
    await test.step("Given I am on the product list page", async () => {
      await signIn(page);
    });

    await test.step("Then the product list passes axe accessibility checks", async () => {
      const { default: AxeBuilder } = await import("@axe-core/playwright");
      const axeResults = await new AxeBuilder({ page })
        .include(".inventory_container")
        .withTags(["wcag2a", "wcag2aa"])
        .analyze();
      expect(
        axeResults.violations.map((v) => v.id).sort(),
        `axe violations: ${JSON.stringify(axeResults.violations, null, 2)}`
      ).toEqual([]);
    });
  });
});

